interface.definition:
a!localVariables(
  local!hasOrgId: a!isNotNullOrEmpty(ri!orgid),
  local!orgTeam: if(
    local!hasOrgId,
    #"_a-0000eef8-4604-8000-9e54-011c48011c48_1134349"(orgId: ri!orgid, isActive: true),
    {}
  ),
  local!teamIds: if(
    a!isNullOrEmpty(local!orgTeam),
    {},
    index(
      local!orgTeam,
      #"urn:appian:record-field:v1:4eb1fdb2-adfe-4b4b-8a61-ccc9f1f5f947/4889b852-272c-42a8-81e1-414933737923",
      {}
    )
  ),
  local!hasTeams: a!isNotNullOrEmpty(local!teamIds),
  {
    /* ── CARD 1: ORGANIZATION TEAMS ── */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sectionLayout_v1"(
          label: "Organization Teams",
          labelSize: "MEDIUM",
          labelColor: "STANDARD",
          contents: {
            if(
              not(local!hasOrgId),
              /* State 1 - No organization selected */
              #"SYSTEM_SYSRULES_columnsLayout"(
                columns: #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "users",
                          size: "LARGE",
                          color: "SECONDARY"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: "Please select an organization to view teams.",
                          color: "SECONDARY"
                        )
                      },
                      align: "CENTER"
                    )
                  }
                ),
                alignVertical: "MIDDLE"
              ),
              if(
                not(local!hasTeams),
                /* State 2 - No teams assigned */
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: #"SYSTEM_SYSRULES_columnLayout"(
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: "inbox",
                            size: "LARGE",
                            color: "SECONDARY"
                          ),
                          char(10),
                          char(10),
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: "No teams assigned to this organization.",
                            color: "SECONDARY"
                          )
                        },
                        align: "CENTER"
                      )
                    }
                  ),
                  alignVertical: "MIDDLE"
                ),
                /* State 3 - Show teams grid only */
                #"_a-0000efd5-dd88-8000-9e5d-011c48011c48_1347749"(orgid: ri!orgid)
              )
            )
          }
        )
      },
      style: "NONE",
      padding: "STANDARD",
      marginBelow: "STANDARD",
      showBorder: true
    ),

    /*   CARD 3: Status  */
    #"SYSTEM_SYSRULES_cardLayout"(
      contents: {
        #"SYSTEM_SYSRULES_sectionLayout_v1"(
          label: "Status Of Request",
          labelSize: "MEDIUM",
          labelColor: "STANDARD",
          contents: {
            if(
              not(local!hasOrgId),
              /* State 1 - No organization selected */
              #"SYSTEM_SYSRULES_columnsLayout"(
                columns: #"SYSTEM_SYSRULES_columnLayout"(
                  contents: {
                    #"SYSTEM_SYSRULES_richTextDisplayField"(
                      labelPosition: "COLLAPSED",
                      value: {
                        #"SYSTEM_SYSRULES_richTextIcon"(
                          icon: "teams",
                          size: "LARGE",
                          color: "SECONDARY"
                        ),
                        char(10),
                        char(10),
                        #"SYSTEM_SYSRULES_richTextItem_v1"(
                          text: "Please select a team and check the status here.",
                          color: "SECONDARY"
                        )
                      },
                      align: "CENTER"
                    )
                  }
                ),
                alignVertical: "MIDDLE"
              ),
              if(
                not(local!hasTeams),
                /* State 2 - No teams assigned */
                #"SYSTEM_SYSRULES_columnsLayout"(
                  columns: #"SYSTEM_SYSRULES_columnLayout"(
                    contents: {
                      #"SYSTEM_SYSRULES_richTextDisplayField"(
                        labelPosition: "COLLAPSED",
                        value: {
                          #"SYSTEM_SYSRULES_richTextIcon"(
                            icon: "inbox",
                            size: "LARGE",
                            color: "SECONDARY"
                          ),
                          char(10),
                          char(10),
                          #"SYSTEM_SYSRULES_richTextItem_v1"(
                            text: "No Request has been rasied",
                            color: "SECONDARY"
                          )
                        },
                        align: "CENTER"
                      )
                    }
                  ),
                  alignVertical: "MIDDLE"
                ),

                  #"_a-0000ef67-4afa-8000-9e56-011c48011c48_1208892"(orgid: ri!orgid),


              )
            )
          }
        )
      },
      style: "NONE",
      padding: "STANDARD",
      marginBelow: "STANDARD",
      showBorder: true
    )
  }
)
